//! `coffee-app`: the ROAST/TTY terminal coffee shop UI, an nsh app in Rust mode.
//!
//! # Frozen public interface
//!
//! Other crates (`coffee-host`, `coffee-sshd`) and tests code against exactly these items.
//! Change them only together with every caller:
//!
//! - [`App`]: the root component. `nsh.json` names it (`"root": "App"`); a host mounts it
//!   with `Root::of::<coffee_app::App>()`.
//! - [`registry()`]: this crate's nsh UI set, generated by `#[native_module("coffee-app/native")]`.
//!   A host passes it next to `nsh_base::registry()` in its `ui_sets`.
//! - [`SessionEnv`] and [`configure`]: the per-session settings the host hands to the UI
//!   before it mounts [`App`]. One process serves exactly one SSH session, so they are a
//!   process-wide `OnceLock`.
//! - [`session_env`]: how the UI reads them back.
//! - [`APP_ID`] and [`THEME_JSON`]: `nsh.json`'s `"id"` and `"theme"` (dark only), which a
//!   host that mounts the root itself applies with `Root::app_id`, `Root::tokens` and
//!   `Root::appearance(Appearance::Dark)` (`nsh run`/`nsh test` do that from `nsh.json`).
//! - The API types: `coffee_api` (re-exported as [`api`]).

use std::sync::OnceLock;

use nsh_base::theme;
use nsh_core::prelude::*;

/// What a TSX entry may import from `coffee-app/native`; also makes `pub fn registry()`.
#[native_module("coffee-app/native")]
fn native(registry: &mut Registry) {
  registry.register::<App>();
}

/// The settings of the one SSH session this process serves.
///
/// The host builds it from its environment (`COFFEE_API_URL` and friends, set by
/// `coffee-sshd`) and passes it to [`configure`] before the UI starts.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct SessionEnv {
  /// Base URL of the local backend, e.g. `http://127.0.0.1:3000`.
  pub api_url: String,
  /// Shared secret the backend expects on internal requests, when it requires one.
  pub internal_key: Option<String>,
  /// SHA-256 fingerprint of the SSH public key the client offered, if any.
  pub ssh_fingerprint: Option<String>,
  /// The SSH client's IP address, for rate limits and logs.
  pub client_ip: Option<String>,
  /// Forced color depth: `truecolor`, `256`, `16` or `mono`; `None` detects it.
  pub color_mode: Option<String>,
}

/// The app's id; `nsh.json` `"id"` is the same.
pub const APP_ID: &str = "dev.yafh.coffee";

/// The app's theme file (`apps/tui/theme.json`, shadcn `cssVars`, dark only), which
/// `nsh.json` `"theme"` names. Read it with `nsh_base::Theme::from_json`.
pub const THEME_JSON: &str = include_str!("../theme.json");

/// The backend API's DTOs.
pub use coffee_api as api;

static SESSION_ENV: OnceLock<SessionEnv> = OnceLock::new();

/// Stores this process's session settings. Call it once, before the UI starts.
///
/// Later calls are ignored: one process serves one session, so the first value wins.
pub fn configure(env: SessionEnv) {
  let _ = SESSION_ENV.set(env);
}

/// The session settings given to [`configure`], or `None` when it was never called
/// (as under `nsh run` / `nsh test`, where the UI falls back to its defaults).
pub fn session_env() -> Option<&'static SessionEnv> {
  SESSION_ENV.get()
}

/// The root component: a static placeholder screen until the shop's pages land.
#[component]
pub fn App() -> impl IntoElement {
  view()
    .flex_1()
    .bg(move || theme().background)
    .text_color(move || theme().foreground)
    .items_center()
    .justify_center()
    .child(text("◆ROAST/TTY").font_weight(FontWeight::BOLD))
    .child(text("演示环境 · 不是真实商店").text_color(move || theme().muted_foreground))
}

#[cfg(test)]
mod tests {
  use super::*;

  #[test]
  fn theme_parses_with_the_design_tokens() {
    let theme = nsh_base::Theme::from_json(THEME_JSON).unwrap();
    assert!(theme.color("success").is_some());
    assert!(theme.color("soft").is_some());
  }

  #[test]
  fn configure_keeps_the_first_value() {
    configure(SessionEnv {
      api_url: "http://127.0.0.1:3000".into(),
      ..SessionEnv::default()
    });
    configure(SessionEnv {
      api_url: "http://ignored".into(),
      ..SessionEnv::default()
    });
    assert_eq!(
      session_env().map(|env| env.api_url.as_str()),
      Some("http://127.0.0.1:3000")
    );
  }
}
